def find_heaviest_coin(coins):
    if len(coins) == 1:
        return coins[0]
    if len(coins) == 2:
        return max(coins)
    if len(coins) == 3:
        return max(coins)
    else:
        n = len(coins)
        A = coins[:n//3]
        B = coins[n//3:2*n//3]
        C = coins[2*n//3:]
        if max(A) > max(B) and max(A) > max(C):
            return find_heaviest_coin(A)
        elif max(B) > max(A) and max(B) > max(C):
            return find_heaviest_coin(B)
        else:
            return find_heaviest_coin(C)
